create or replace function pg_temp.check_true(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERTION: %',msg; end if; end $$;
create or replace function pg_temp.expect_error(q text) returns void language plpgsql as $$ declare caught boolean:=false; begin begin execute q; exception when others then caught:=true; end; if not caught then raise exception 'EXPECTED_ERROR_NOT_RAISED'; end if; end $$;
do $test$ declare v jsonb;r jsonb;j int;ok boolean:=false;msg text; begin begin v:=public.novacart_prepare('{"external_id": "db-journey-1", "email": "customer001@example.invalid", "order_id": "NC-O0001", "message": "I ordered a laptop 10 days ago, but it has not arrived. I want a refund.", "verified_identity": true}'::jsonb); r:=public.novacart_finalize(jsonb_build_object('ticket_id',v->>'ticket_id','agents','[{"agent": "Orchestrator", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "Intent Classification", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "Knowledge Retrieval", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "Order Resolution", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "Refund Decision", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "Customer Response", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "Human Escalation", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}, {"agent": "QA Evaluation", "model": "test-fixture-not-live-ai", "output": {"summary": "Database integration fixture", "action": "human_review", "policy_ids": [], "confidence": 1, "needs_human": true, "flags": []}}]'::jsonb)); perform pg_temp.check_true(r->>'status'='review','review state'); perform pg_temp.check_true((select count(*)=8 from public.novacart_agent_executions where ticket_id=(v->>'ticket_id')::uuid),'8 fixture records'); perform pg_temp.check_true((select count(*)=2 from public.novacart_outbox where ticket_id=(v->>'ticket_id')::uuid and status='held'),'held outbound'); perform pg_temp.check_true((select count(*)=1 from public.novacart_audit_logs where entity=v->>'ticket_id'),'audit recorded'); raise exception 'TEST_ROLLBACK_OK'; exception when others then msg:=SQLERRM;ok:=msg='TEST_ROLLBACK_OK'; end; insert into public.novacart_test_results(run_id,scenario,passed,evidence) values('db-suite-v2','DB journey 01: owned order through review and audit',ok,jsonb_build_object('scope','actual Supabase database integration; AI outputs are fixtures','detail',msg)); end $test$;
